function indiceDificultad(dificultad) {
    switch (dificultad) {
        case DIF_RUT :
        case DIF_RUT3 :
        case DIF_RUT_VALOR :
            return 1;
        case DIF_FAC :
        case DIF_FAC3 :
        case DIF_FAC_VALOR :
            return 2;
        case DIF_MED :
        case DIF_MED3 :
        case DIF_MED_VALOR :
            return 3;
        case DIF_DIF :
        case DIF_DIF3 :
        case DIF_DIF_VALOR :
            return 4;
        case DIF_MDF :
        case DIF_MDF3 :
        case DIF_MDF_VALOR :
            return 5;
        case DIF_ABS :
        case DIF_ABS3 :
        case DIF_ABS_VALOR :
            return 6;
        case DIF_CIM :
        case DIF_CIM3 :
        case DIF_CIM_VALOR :
            return 7;
        case DIF_IMP :
        case DIF_IMP3 :
        case DIF_IMP_VALOR :
            return 8;
        case DIF_INH :
        case DIF_INH3 :
        case DIF_INH_VALOR :
            return 9;
        case DIF_ZEN :
        case DIF_ZEN3 :
        case DIF_ZEN_VALOR :
            return 10;
        default:
            throw ERR_DIFICULTAD_DESCONOCIDA;
    }
}

