/**
 *
 * @class Equipo
 * @param {string} nombre
 * @param {Dinero} costeDinero
 * @param {number} peso
 * @param {string} disponibilidad
 * @param {number} entereza
 * @param {number} presencia
 * @param {number} bonoHabilidad
 * @param {boolean} [noComprable]
 * @constructor
 */
function Equipo(nombre, costeDinero, peso, disponibilidad, entereza, presencia, bonoHabilidad, noComprable) {
    /**
     *
     * @type {string}
     */
    this.nombre = nombre;

    /**
     *
     * @type {Dinero}
     */
    this.costeDinero = costeDinero;
    /**
     *
     * @type {number}
     */
    this.peso = peso;
    /**
     *
     * @type {string}
     */
    this.disponibilidad = disponibilidad;
    /**
     *
     * @type {number}
     */
    this.entereza = entereza;
    /**
     *
     * @type {number}
     */
    this.presencia = presencia;
    /**
     *
     * @type {number}
     */
    this.bonoHabilidad = bonoHabilidad;

    if (noComprable)
        this.noComprable = true;
    else
        this.noComprable = false;
}

Equipo.prototype = {
    constructor: Equipo,

    /**
     *
     * @returns {string}
     */
    getNombre : function() {
        return this.nombre;
    },

    /**
     *
     * @returns {boolean}
     */
    isNoComprable : function() {
        return this.noComprable;
    },

    /**
     *
     * @param {string} valor
     */
    setNombre : function(valor) {
        this.nombre = valor;
    },

    /**
     *
     * @returns {Dinero}
     */
    getCosteDinero : function() {
        return this.costeDinero;
    },

    /**
     *
     * @returns {number}
     */
    getPeso : function() {
        return this.peso;
    },

    /**
     *
     * @returns {string}
     */
    getDisponibilidad : function() {
        return this.disponibilidad;
    },

    /**
     *
     * @param {string} valor
     */
    setDisponibilidad : function(valor) {
        this.disponibilidad = valor;
    },

    /**
     *
     * @returns {number}
     */
    getEntereza : function() {
        return this.entereza;
    },

    /**
     *
     * @returns {number}
     */
    getPresencia : function() {
        return this.presencia;
    },

    /**
     *
     * @returns {number}
     */
    getBonoHabilidad : function() {
        return this.bonoHabilidad;
    },

    /**
     *
     * @returns {Equipo}
     */
    duplicar: function() {
        return new Equipo(this.nombre, this.costeDinero, this.peso, this.disponibilidad, this.entereza, this.presencia, this.bonoHabilidad);
    },

    toString: function() {
        return _l(this.nombre);
    },

    toJSON : function() {
        return this.nombre;
    }
};

/**
 *
 * @class Arma
 * @extends {Equipo}
 * @param {string} nombre
 * @param {Dinero} costeDinero
 * @param {number} peso
 * @param {string} disponibilidad
 * @param {string[]} categorias
 * @param {number} velocidad
 * @param {number} dmgBase
 * @param {number} entereza
 * @param {number} rotura
 * @param {number} fueReq
 * @param {number} fueReq2manos
 * @param {number} presencia
 * @param {string} criticoPrimario
 * @param {string} criticoSecundario
 * @param {string[]} especial
 * @param {string} bonoDmg
 * @param {boolean} [noComprable]
 * @constructor
 */
function Arma(nombre, costeDinero, peso, disponibilidad, categorias, velocidad, dmgBase, entereza, rotura, fueReq, fueReq2manos, presencia, criticoPrimario, criticoSecundario, especial, bonoDmg, noComprable) {
    if (!noComprable)
        noComprable = false;
    Arma.parent.constructor.call(this,nombre,costeDinero,peso,disponibilidad,entereza,presencia,0,noComprable);

    /** @type string[] */
    this.categorias = categorias;

    /** @type number */
    this.velocidad = velocidad;

    /** @type number */
    this.dañoBase = dmgBase;

    /** @type number */
    this.rotura = rotura;

    /** @type number */
    this.fueReq = fueReq;

    /** @type number */
    this.fueReq2manos = fueReq2manos;

    /** @type string */
    this.criticoPrimario = criticoPrimario;

    /** @type string */
    this.criticoSecundario = criticoSecundario;

    /** @type string[] */
    this.especial = especial;

    /** @type string */
    this.bonoDaño = bonoDmg;

    /** @type number */
    this.modificadorAtaqueParada = 0;

    /** @type number */
    this.modificadorTADefensor = 0;

}

extend(Arma,Equipo);

/**
 *
 * @returns {string}
 */
Arma.prototype.getCategoria = function() {
    var categoria = "";

    for (var i = 0; i < this.categorias.length; i++) {
        categoria += this.categorias[i];
        if (i+1 < this.categorias.length) {
            categoria += "/";
        }
    }

    return categoria;
}

/**
 *
 * @returns {string} Ya localizado
 */
Arma.prototype.getCategoriaLoc = function() {
    var categoria = "";

    for (var i = 0; i < this.categorias.length; i++) {
        categoria += _l(this.categorias[i]);
        if (i+1 < this.categorias.length) {
            categoria += "/";
        }
    }

    return categoria;
}

/**
 *
 * @returns {string[]}
 */
Arma.prototype.getCategorias = function() {
    return this.categorias;
};

/**
 *
 * @returns {number}
 */
Arma.prototype.getVelocidad = function() {
    return this.velocidad;
};

