function cargarPersonaje(cadena) {
    personaje_actual = new Personaje();

    var allHabilidades;

    json_parse(cadena, function(k, v) {
        switch (k) {
            case 'raza' :
                personaje_actual.raza = getRaza(v);
                break;
            case 'categoria':
            case 'proximaCategoria':
                personaje_actual[k] = getCategoria(v);
                break;
            case 'aumentosCaracteristicas':
                personaje_actual.aumentosCaracteristicas = parseArrayAumentosCaracteristicas(v);
                break;
            case 'categoriasPorNiveles':
                personaje_actual.categoriasPorNiveles = parseArrayCategorias(v);
                break;
            case 'armadurasNaturales':
                personaje_actual[k] = parseArrayTiposArmadura(v);
                break;
            case 'armaduraNatural':
            case 'capaYelmo':
                personaje_actual[k] = parseTipoArmadura(v);
                break;
            case 'elan':
                personaje_actual[k] = parseArrayElan(v);
                break;
            case 'viasMagia':
                personaje_actual[k] = parseArrayNivelEnVia(v);
                break;
            case 'conjurosSueltos':
                personaje_actual[k] = parseArrayConjuros(v);
                break;
            case 'bonos':
                personaje_actual[k] = parseArrayBonos(v);
                break;
            case 'costesReducidos':
                personaje_actual[k] = parseArrayCostesReducidos(v);
                break;
            case 'bonificadoresNaturales':
                personaje_actual[k] = parseArrayBonificadoresNaturales(v);
                break;
            case 'ventajas':
            case 'desventajas':
                personaje_actual[k] = parseArrayElementoPCComprado(v);
                break;
            case 'prohibidos':
                personaje_actual[k] = parseArrayElementoProhibido(v);
                break;
            case 'allHabilidades':
                allHabilidades = v;
                break;
            case 'manejoArmas':
                personaje_actual[k] = parseArrayArma(v);
                break;
            case 'tablasArmas':
                personaje_actual[k] = parseArrayTablasArmasComprada(v);
                break;
            case 'artesMarciales':
                personaje_actual[k] = parseArrayArtesMarcialesCompradas(v);
                break;
            case 'habilidadesKi':
                personaje_actual[k] = parseArrayHabilidadKiComprada(v);
                break;
            case 'tecnicasKi':
                personaje_actual[k] = parseArrayTecnicaKiComprada(v);
                break;
            case 'numTecnicas':
                personaje_actual.numTecnicas = parseNumTecnicas(v);
                break;
            case 'arsMagnus':
                personaje_actual[k] = parseArrayArsMagnusComprado(v);
                break;
            case 'disciplinasPsiquicas':
                personaje_actual[k] = parseArrayDisciplinaPsiquicaAccedida(v);
                break;
            case 'invocaciones':
                personaje_actual[k] = parseArrayInvocaciones(v);
                break;
            case 'esferasMetamagicas':
                personaje_actual[k] = parseArrayEsferasMetamagicasCompradas(v);
                break;
            case 'poderesPsiquicosDominados':
                personaje_actual[k] = parseArrayPoderPsiquicoDominado(v);
                break;
            case 'patronesMentales':
                personaje_actual[k] = parseArrayPatronesMentalesComprados(v);
                break;
            case 'dinero':
                personaje_actual[k] = parseDinero(v);
                break;
            case 'equipo':
                var armas = [];
                var armaduras = [];
                var yelmos = [];
                var equipo = [];
                parseArrayEquipo(v,armas,armaduras,yelmos,equipo);
                personaje_actual.equipoComprado = equipo;
                personaje_actual.armas = armas;
                personaje_actual.armaduras = armaduras;
                personaje_actual.yelmos = yelmos;
                break;
            case 'equipoComprado':
                personaje_actual[k] = parseArrayEquipoComprado(v);
                break;
            case 'armas':
                personaje_actual[k] = parseArrayArmaComprada(v);
                break;
            case 'armaduras':
                personaje_actual[k] = parseArrayArmaduraComprada(v);
                break;
            case 'yelmos':
                personaje_actual[k] = parseArrayYelmoComprado(v);
                break;
            default:
                personaje_actual[k] = v;
        }
    });

    if (personaje_actual['armaduraNatural']) {
        if (personaje_actual.hasVentaja(getVentaja(VENT_ARMADURA_MISTICA),"")) {
            armaduraMistica(0,0,true);
        }
        if (personaje_actual.hasVentaja(getVentaja(VENT_ARMADURA_NATURAL),"")) {
            armaduraNatural(0,0,true);
        }
        var bonos = personaje_actual.getBonos(BONO_ARMADURA_NATURAL,"",CATEGORIA_BONO_CUALQUIERA);
        for (var x = 0; x < bonos.length; x++) {
            personaje_actual.addArmaduraNatural([bonos[x].bono,bonos[x].bono,bonos[x].bono,bonos[x].bono,bonos[x].bono,bonos[x].bono,bonos[x].bono],(bonos[x].getOpcion() == ARMADURA_CLASE_BLANDA));
        }

        delete personaje_actual['armaduraNatural'];
    }

    personaje_actual['allHabilidades'] = parseArrayHabilidadDePersonaje(allHabilidades);

    mostrarPersonajeActual();
    PERSONAJE_EN_MARCHA = true;
}

/* ==== ./js/init.js ==== */
animaUnico.inicializar = function() {
    initHabilidades();

    initVentajas();

    initEquipo();

    initArtesMarciales();

    initCategorias();

    muestraControles();

    setIdiomaUI();

    localizaHTML();

    /*Se extraen los valores de GET*/
    var queryDict = {};
    location.search.substr(1).split("&").forEach(
        function(item) {
            queryDict[item.split("=")[0]] = item.split("=")[1]
        }
    );

    if (queryDict.carga == 1) {
        var idPersonaje = queryDict.id;
        jQuery.ajax('http://helechaloscuro.net/cake/personajes/carga/'+idPersonaje,{
            success : function(json, status, jqxhr) {
                cargarPersonaje(json);
                ALTO_DIALOGO =  $(window).height() * 0.8;
            },
            dataType : 'text',
            error : function(jqxhrm, errorType, exception) {

            } //TODO username / password para autenticación HTTP
        });
    } else {
        personaje_actual = new Personaje();
//        personaje_actual.setRaza(getRaza(RAZA_HUMANO));
  //      personaje_actual.setCategoria(CATEGORIA_NOVEL);

        muestraPersonaje(personaje_actual);

        var primeraVisita = true;

        if (typeof(Storage) !== "undefined") {
            if (localStorage.ultimosCambiosVistos == CURRENT_VERSION) {
                primeraVisita = false;
            }
        }

        if (primeraVisita) {
            mostrarLogCambios();
        }
        ALTO_DIALOGO =  $(window).height() * 0.8;
    }

    inicializarAreasContraibles();

};

